  "query": "SELECT campaign.id, campaign.name, metrics.impressions, metrics.clicks, metrics.all_conversions, metrics.all_conversions_value, metrics.cost_per_all_conversions, metrics.value_per_all_conversions, metrics.cost_micros FROM campaign WHERE campaign.advertising_channel_type = 'PERFORMANCE_MAX' AND campaign.status = 'ENABLED' AND segments.date DURING LAST_30_DAYS AND campaign.name NOT LIKE '%00:00:00%' ORDER BY metrics.cost_micros DESC"
}

